"""Routes for Script Jobs, generated by Dryv; the engine implements ScriptsScriptJobsService."""

from __future__ import annotations

from abc import ABC, abstractmethod
from collections.abc import Awaitable, Callable
from typing import Annotated
from uuid import UUID

from fastapi import APIRouter, Body, Depends, Path, Request

from mzizi_engine.api.schemas.api.scripts.models.script_job import ScriptJob
from mzizi_engine.api.schemas.api.scripts.models.script_request import ScriptRequest

__all__ = ["ScriptsScriptJobsService", "build_scripts_script_jobs_router"]

type Guard = Callable[[Request], Awaitable[None]]
"""An async FastAPI dependency that raises 401 or 403 before the route runs."""


class ScriptsScriptJobsService(ABC):
    """What Script Jobs needs from handwritten code. Raise ``fastapi.HTTPException`` for failures."""

    @abstractmethod
    async def cancel_script(self, *, job_id: UUID) -> ScriptJob:
        """Request cancellation of an active script."""

    @abstractmethod
    async def get_script(self, *, job_id: UUID) -> ScriptJob:
        """Read the current script state and recorded output."""

    @abstractmethod
    async def submit_script(self, *, script: ScriptRequest) -> ScriptJob:
        """Start a bounded data transformation over verified artifacts."""


def build_scripts_script_jobs_router(service: ScriptsScriptJobsService, guard: Guard | None = None) -> APIRouter:
    """Routes for Script Jobs, delegating to ``service``; ``guard`` protects every route."""

    router = APIRouter(tags=["Script Jobs"], dependencies=[Depends(guard)] if guard else [])

    @router.post(
        "/v1/research/scripts/{jobId}/cancel",
        response_model=ScriptJob,
        status_code=200,
        summary="Request cancellation of an active script.",
    )
    async def cancel_script(
        job_id: Annotated[UUID, Path(alias="jobId")],
    ) -> ScriptJob:
        return await service.cancel_script(job_id=job_id)

    @router.get(
        "/v1/research/scripts/{jobId}",
        response_model=ScriptJob,
        status_code=200,
        summary="Read the current script state and recorded output.",
    )
    async def get_script(
        job_id: Annotated[UUID, Path(alias="jobId")],
    ) -> ScriptJob:
        return await service.get_script(job_id=job_id)

    @router.post(
        "/v1/research/scripts",
        response_model=ScriptJob,
        status_code=202,
        summary="Start a bounded data transformation over verified artifacts.",
    )
    async def submit_script(
        script: Annotated[ScriptRequest, Body()],
    ) -> ScriptJob:
        return await service.submit_script(script=script)

    return router
